// isPublicGoodURL reports whether a URL points at the sigstore public good
// instance (production or staging).
func isPublicGoodURL(rawURL string) bool {
	if rawURL == "" {
		return false
	}
	parsed, err := url.Parse(rawURL)
	if err != nil || parsed.Hostname() == "" {
		return false
