	var b64sig string
	targetSig, err := blob.LoadFileOrURL(sigRef)
	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}
		targetSig = []byte(sigRef)
	}

	_, err = base64.StdEncoding.DecodeString(string(targetSig))

	if err == nil {
		b64sig = string(targetSig)
	} else {
		b64sig = base64.StdEncoding.EncodeToString(targetSig)
	}

	var payload []byte
	if co.PayloadRef != "" {
		payload, err = blob.LoadFileOrURL(co.PayloadRef)
		if err != nil {
			return nil, err
		}
	} else {
		digest, err := ociremote.ResolveDigest(signedImgRef, co.RegistryClientOpts...)
		if err != nil {
			return nil, err
		}
		payload, err = ObsoletePayload(ctx, digest, co.Annotations)
		if err != nil {
			return nil, err
		}
	}

	var opts []static.Option
	if co.SigVerifier != nil {
		if cb, ok := co.SigVerifier.(interface{ GetCert() *x509.Certificate }); ok {
			if cert := cb.GetCert(); cert != nil {
				var chain []*x509.Certificate
				if ch, ok := co.SigVerifier.(interface{ GetChain() []*x509.Certificate }); ok {
					chain = ch.GetChain()
				}

				certPEM, err := cryptoutils.MarshalCertificateToPEM(cert)
				if err != nil {
					return nil, err
				}
				var chainPEM []byte
				if len(chain) > 0 {
					chainPEM, err = cryptoutils.MarshalCertificatesToPEM(chain)
					if err != nil {
						return nil, err
					}
				}

				opts = append(opts, static.WithCertChain(certPEM, chainPEM))
			}
		}
	}

	sig, err := static.NewSignature(payload, b64sig, opts...)
	if err != nil {
		return nil, err
	}
	return &fakeOCISignatures{
		signatures: []oci.Signature{sig},
	}, nil
}

