		},
		RunDetails: provenanceRunDetails{
			Builder: provenanceBuilder{ID: provenanceBuilderID},
		},
	})
	if err != nil {
		return nil, fmt.Errorf("marshaling index provenance: %w", err)
	}
	return &Provenance{
		PredicateType: ProvenancePredicateType,
		Predicate:     predicate,
	}, nil
}

func goBuildEnv(env []string) map[string]string {
	keys := map[string]struct{}{
		"CGO_ENABLED":   {},
		"GO111MODULE":   {},
		"GO386":         {},
		"GOAMD64":       {},
		"GOARCH":        {},
		"GOARM":         {},
		"GOEXPERIMENT":  {},
		"GOFLAGS":       {},
		"GOMIPS":        {},
		"GOMIPS64":      {},
		"GOPPC64":       {},
		"GORISCV64":     {},
		"GOSUMDB":       {},
		"GOTOOLCHAIN":   {},
		"GOWASM":        {},
	}
	result := map[string]string{}
	for _, kv := range env {
		key, value, ok := splitEnv(kv)
		if !ok {
			continue
		}
		if _, ok := keys[key]; ok {
			result[key] = value
		}
	}
	if len(result) == 0 {
		return nil
	}
	return result
}

func splitEnv(kv string) (string, string, bool) {
	for i := 0; i < len(kv); i++ {
		if kv[i] == '=' {
			return kv[:i], kv[i+1:], true
		}
	}
	return "", "", false
}

