const inTotoStatementType = "https://in-toto.io/Statement/v1"

// Signer signs an arbitrary payload.
type Signer interface {
	Sign([]byte) ([]byte, error)
}

// SignerFunc adapts a function to the Signer interface.
type SignerFunc func([]byte) ([]byte, error)

// Sign implements Signer.
func (f SignerFunc) Sign(payload []byte) ([]byte, error) {
	return f(payload)
}

type attestationStatement struct {
	Type          string               `json:"_type"`
	Subject       []attestationSubject `json:"subject"`
	PredicateType string               `json:"predicateType"`
	Predicate     json.RawMessage      `json:"predicate"`
}

type attestationSubject struct {
	Name   string            `json:"name"`
	Digest map[string]string `json:"digest"`
}

type dsseEnvelope struct {
	PayloadType string          `json:"payloadType"`
	Payload     string          `json:"payload"`
	Signatures  []dsseSignature `json:"signatures"`
}

type dsseSignature struct {
	KeyID string `json:"keyid"`
	Sig   string `json:"sig"`
}

func passwordFromEnv(bool) ([]byte, error) {
	if password, ok := os.LookupEnv("COSIGN_PASSWORD"); ok {
		return []byte(password), nil
	}
	return nil, errors.New("COSIGN_PASSWORD must be set when the signing key is encrypted")
}

func signerFromKey(_ context.Context, keyRef string) (Signer, error) {
	raw, err := os.ReadFile(keyRef)
	if err != nil {
		return nil, fmt.Errorf("reading signing key: %w", err)
	}
	privateKey, err := cryptoutils.UnmarshalPEMToPrivateKey(raw, passwordFromEnv)
	if err != nil {
		return nil, fmt.Errorf("parsing signing key: %w", err)
	}
	signer, err := signature.LoadSigner(privateKey, crypto.SHA256)
	if err != nil {
		return nil, err
	}
	return SignerFunc(func(payload []byte) ([]byte, error) {
		return signer.SignMessage(bytes.NewReader(payload))
	}), nil
}

func (d *defalt) signEntity(ctx context.Context, repo name.Repository, se oci.SignedEntity) error {
	d.signMu.Lock()
	defer d.signMu.Unlock()

	h, err := se.Digest()
	if err != nil {
		return err
	}
	digest := repo.Digest(h.String())

	signaturePayload, err := json.Marshal(map[string]any{
		"critical": map[string]any{
			"identity": map[string]string{
				"docker-reference": repo.Name(),
			},
			"image": map[string]string{
				"docker-manifest-digest": h.String(),
			},
			"type": "cosign container image signature",
		},
		"optional": nil,
	})
	if err != nil {
		return fmt.Errorf("marshaling signature payload: %w", err)
	}
	signature, err := d.signer.Sign(signaturePayload)
	if err != nil {
		return fmt.Errorf("signing %s: %w", digest, err)
	}
	ociSignature, err := static.NewSignature(signaturePayload, base64.StdEncoding.EncodeToString(signature))
	if err != nil {
		return fmt.Errorf("creating signature: %w", err)
	}
	signed, err := ocimutate.AttachSignatureToEntity(se, ociSignature)
	if err != nil {
		return fmt.Errorf("attaching signature: %w", err)
	}
	if err := ociremote.WriteSignatures(repo, signed, d.oopt...); err != nil {
		return fmt.Errorf("writing signature for %s: %w", digest, err)
	}
	log.Printf("Signed %v", digest)

	provenance, err := provenanceFor(se, digest)
	if err != nil {
		return err
	}
	statement, err := json.Marshal(attestationStatement{
		Type: inTotoStatementType,
		Subject: []attestationSubject{{
			Name:   repo.String(),
			Digest: map[string]string{h.Algorithm: h.Hex},
		}},
		PredicateType: provenance.PredicateType,
		Predicate:     provenance.Predicate,
	})
	if err != nil {
		return fmt.Errorf("marshaling in-toto statement: %w", err)
	}
	envelope, err := signDSSE(d.signer, ctypes.IntotoPayloadType, statement)
	if err != nil {
		return fmt.Errorf("signing provenance for %s: %w", digest, err)
	}
	attestation, err := static.NewAttestation(
		envelope,
		static.WithLayerMediaType(ctypes.DssePayloadType),
		static.WithAnnotations(map[string]string{"predicateType": provenance.PredicateType}),
	)
	if err != nil {
		return fmt.Errorf("creating attestation: %w", err)
	}
	attested, err := ocimutate.AttachAttestationToEntity(signed, attestation)
	if err != nil {
		return fmt.Errorf("attaching attestation: %w", err)
	}
	if err := ociremote.WriteAttestations(repo, attested, d.oopt...); err != nil {
		return fmt.Errorf("writing attestation for %s: %w", digest, err)
	}
	log.Printf("Attested %v", digest)
	return nil
}

func signDSSE(signer Signer, payloadType string, payload []byte) ([]byte, error) {
	pae := []byte(fmt.Sprintf("DSSEv1 %d %s %d %s", len(payloadType), payloadType, len(payload), payload))
	signature, err := signer.Sign(pae)
	if err != nil {
		return nil, err
	}
	return json.Marshal(dsseEnvelope{
		PayloadType: payloadType,
		Payload:     base64.StdEncoding.EncodeToString(payload),
		Signatures: []dsseSignature{{
			Sig: base64.StdEncoding.EncodeToString(signature),
		}},
	})
}

func provenanceFor(se oci.SignedEntity, digest name.Digest) (*build.Provenance, error) {
	if result, ok := se.(build.ProvenanceResult); ok {
		provenance, err := result.Provenance()
		if err != nil {
			return nil, fmt.Errorf("getting provenance for %s: %w", digest, err)
		}
		if provenance != nil {
			return provenance, nil
		}
	}
	return fallbackProvenance(digest), nil
}

func fallbackProvenance(digest name.Digest) *build.Provenance {
	predicate, err := json.Marshal(map[string]any{
		"buildDefinition": map[string]any{
			"buildType": build.ProvenanceBuildType,
			"externalParameters": map[string]string{
				"artifact": digest.String(),
			},
		},
		"runDetails": map[string]any{
			"builder": map[string]string{
				"id": "https://github.com/ko-build/ko",
			},
		},
	})
	if err != nil {
		panic(err)
	}
	return &build.Provenance{
		PredicateType: build.ProvenancePredicateType,
		Predicate:     predicate,
	}
}

// Option is a functional option for NewDefault.
type Option func(*defaultOpener) error

type defaultOpener struct {
	base       string
	t          http.RoundTripper
	userAgent  string
	keychain   authn.Keychain
	namer      Namer
	tags       []string
	tagOnly    bool
	insecure   bool
	ropt       []remote.Option
	jobs       int
	signingKey string
	signer     Signer
}

// Namer is a function from a supported import path to the portion of the resulting
// image name that follows the "base" repository name.
type Namer func(string, string) string

// identity is the default namer, so import paths are affixed as-is under the repository
// name for maximum clarity, e.g.
//
//	gcr.io/foo/github.com/bar/baz/cmd/blah
//	^--base--^ ^-------import path-------^
func identity(base, in string) string { return path.Join(base, in) }

// As some registries do not support pushing an image by digest, the default tag for pushing
// is the 'latest' tag.
const latestTag = "latest"

func (do *defaultOpener) Open() (Interface, error) {
	if do.tagOnly {
		if len(do.tags) != 1 {
			return nil, errors.New("must specify exactly one tag to resolve images into tag-only references")
		}
		if do.tags[0] == latestTag {
			return nil, errors.New("latest tag cannot be used in tag-only references")
		}
	}

	pusher, err := remote.NewPusher(do.ropt...)
	if err != nil {
		return nil, err
	}

	oopt := []ociremote.Option{ociremote.WithRemoteOptions(do.ropt...)}

	// Respect COSIGN_REPOSITORY
	targetRepoOverride, err := ociremote.GetEnvTargetRepository()
	if err != nil {
		return nil, err
	}
	if (targetRepoOverride != name.Repository{}) {
		oopt = append(oopt, ociremote.WithTargetRepository(targetRepoOverride))
	}

	signer := do.signer
	if signer == nil && do.signingKey != "" {
		signer, err = signerFromKey(context.Background(), do.signingKey)
		if err != nil {
			return nil, fmt.Errorf("loading signing key %q: %w", do.signingKey, err)
		}
	}

	return &defalt{
		base:     do.base,
		namer:    do.namer,
		tags:     do.tags,
		tagOnly:  do.tagOnly,
		insecure: do.insecure,
		jobs:     do.jobs,
		pusher:   pusher,
		oopt:     oopt,
		signer:   signer,
	}, nil
}

// NewDefault returns a new publish.Interface that publishes references under the provided base
// repository using the default keychain to authenticate and the default naming scheme.
func NewDefault(base string, options ...Option) (Interface, error) {
	do := &defaultOpener{
		base:      base,
		t:         remote.DefaultTransport,
		userAgent: "ko",
		keychain:  authn.DefaultKeychain,
		namer:     identity,
		tags:      []string{latestTag},
	}

	for _, option := range options {
		if err := option(do); err != nil {
			return nil, err
			return nil, err
		}
	}

	do.ropt = []remote.Option{remote.WithAuthFromKeychain(do.keychain), remote.WithTransport(do.t), remote.WithUserAgent(do.userAgent)}
	if do.jobs == 0 {
		do.jobs = runtime.GOMAXPROCS(0)
		do.ropt = append(do.ropt, remote.WithJobs(do.jobs))
	}

	return do.Open()
}

func (d *defalt) pushResult(ctx context.Context, tag name.Tag, br build.Result) error {
	mt, err := br.MediaType()
